#!/usr/bin/env python3
"""Drive /workspace/executable -r in a pty. Feed given inputs, capture raw bytes."""
import os, pty, sys, time, select, signal

def run(inputs, wait=0.4, final_wait=0.8, args=("-r",), env=None):
    """inputs: list of byte strings to write with delay. Returns (output_bytes, exit_status_or_None)."""
    pid, fd = pty.fork()
    if pid == 0:
        e = dict(os.environ)
        if env: e.update(env)
        os.execve("/workspace/executable", ["/workspace/executable"] + list(args), e)
    out = b""
    def drain(timeout):
        nonlocal out
        end = time.time() + timeout
        while time.time() < end:
            r, _, _ = select.select([fd], [], [], max(0, end - time.time()))
            if fd in r:
                try:
                    data = os.read(fd, 65536)
                except OSError:
                    break
                if not data:
                    break
                out += data
    drain(0.8)  # initial prompt
    for chunk in inputs:
        try:
            os.write(fd, chunk)
        except OSError:
            break
        drain(wait)
    drain(final_wait)
    status = None
    done, st = os.waitpid(pid, os.WNOHANG)
    if done:
        status = os.waitstatus_to_exitcode(st)
    else:
        os.kill(pid, signal.SIGKILL)
        os.waitpid(pid, 0)
    os.close(fd)
    return out, status

if __name__ == "__main__":
    name = sys.argv[1]
    cases = {
        "one_expr": ([b"some of <word>;\n"], {}),
        "empty_then_expr": ([b"\n", b"5 of \"a\";\n"], {}),
    }
    if name in cases:
        inp, kw = cases[name]
    else:
        inp = [s.encode() for s in sys.argv[2:]]
        kw = {}
    out, st = run(inp, **kw)
    print("STATUS:", st)
    sys.stdout.buffer.write(b"RAW:\n")
    sys.stdout.buffer.write(out)
    print()
    print("REPR:", repr(out))

#!/usr/bin/env python3
"""Run executable with stdin/stdout/stderr on separate ptys or pipes."""
import os, pty, sys, time, select, signal

EXE = "/workspace/executable"

def open_pty_pair():
    m, s = os.openpty()
    return m, s

def run2(inputs, args=("-r",), stdin_tty=True, stdout_tty=True, stderr_tty=True,
         wait=0.35, final_wait=0.7, env=None):
    # returns dict of captured bytes per stream + status
    fds_to_close = []
    if stdin_tty:
        stdin_m, stdin_s = open_pty_pair()
    else:
        stdin_r, stdin_w = os.pipe()
        stdin_s, stdin_m = stdin_r, stdin_w
    if stdout_tty:
        stdout_m, stdout_s = open_pty_pair()
    else:
        stdout_m, stdout_s = os.pipe()  # read, write
    if stderr_tty:
        stderr_m, stderr_s = open_pty_pair()
    else:
        stderr_m, stderr_s = os.pipe()

    pid = os.fork()
    if pid == 0:
        os.setsid()
        os.dup2(stdin_s, 0)
        os.dup2(stdout_s, 1)
        os.dup2(stderr_s, 2)
        for fd in (stdin_m, stdout_m, stderr_m):
            try: os.close(fd)
            except OSError: pass
        e = dict(os.environ)
        if env: e.update(env)
        os.execve(EXE, [EXE] + list(args), e)
        os._exit(127)

    for fd in (stdin_s, stdout_s, stderr_s):
        os.close(fd)

    caps = {"stdin_echo": b"", "stdout": b"", "stderr": b""}
    readers = {stdin_m: "stdin_echo", stdout_m: "stdout", stderr_m: "stderr"}

    def drain(timeout):
        end = time.time() + timeout
        while time.time() < end:
            rl = [fd for fd in readers]
            if not rl: break
            r, _, _ = select.select(rl, [], [], max(0, end - time.time()))
            for fd in r:
                try:
                    data = os.read(fd, 65536)
                except OSError:
                    data = b""
                if not data:
                    readers.pop(fd, None)
                else:
                    caps[readers[fd]] += data

    drain(0.7)
    for chunk in inputs:
        try:
            os.write(stdin_m, chunk)
        except OSError:
            break
        drain(wait)
    drain(final_wait)
    status = None
    done, st = os.waitpid(pid, os.WNOHANG)
    if done:
        status = os.waitstatus_to_exitcode(st)
    else:
        os.kill(pid, signal.SIGKILL)
        os.waitpid(pid, 0)
    for fd in (stdin_m, stdout_m, stderr_m):
        try: os.close(fd)
        except OSError: pass
    return caps, status

if __name__ == "__main__":
    pass

